import type { BeliefState, Parcel, Position } from "../domain.js";
import type { AgentCapability } from "./contracts.js";

/** Legacy implementation detail; not advertised as a predeclared capability. */
export const taskSelectionModule: AgentCapability = {
  id: "task-selection",
  version: 1,
  purpose: "Rank visible work items. The initial policy uses reward divided by Manhattan distance and energy efficiency.",
};

export function selectParcel(state: BeliefState, from: Position): Parcel | undefined {
  return [...state.parcels.values()]
    .filter((parcel) => !parcel.carriedBy)
    .sort((a, b) => utility(b, from, state.energy) - utility(a, from, state.energy))[0];
}

function utility(parcel: Parcel, from: Position, energy: number): number {
  const distance = Math.abs(parcel.x - from.x) + Math.abs(parcel.y - from.y);
  const energyCost = distance * 0.1;
  return parcel.reward / (1 + distance + energyCost / energy);
}

